<script setup lang="ts">
import {computed,ref,watch,nextTick,onBeforeUnmount} from 'vue';
import {ApiError} from './api';import {materialGet} from './material-api';import {validResponse,verifyText,type MaterialEntry} from './material-reader';import {materialCopy} from './material-i18n';
const props=defineProps<{lang:'zh'|'en';scope:string;epoch:number;cid:string;pid:string;revision:number;allowed:boolean;upgrade:boolean}>();
const emit=defineEmits<{close:[];denied:[];language:[]}>();const t=computed(()=>materialCopy[props.lang]);
const dialog=ref<HTMLDialogElement|null>(null),entries=ref<MaterialEntry[]>([]),material=ref<MaterialEntry|null>(null),status=ref<'loading'|'failed'|'missing'|'denied'|'invalid'|''>('loading'),readRevision=ref(0),selected=ref('');
let sequence=0,alive=true,controller:AbortController|null=null;
function stop(){sequence++;controller?.abort();controller=null;}
function close(){stop();emit('close');}
async function read(version?:string){stop();const seq=sequence,scope=props.scope,epoch=props.epoch,cid=props.cid,pid=props.pid;controller=new AbortController();const signal=controller.signal;material.value=null;status.value='loading';selected.value=version??'';
 const same=()=>alive&&seq===sequence&&scope===props.scope&&epoch===props.epoch&&cid===props.cid&&pid===props.pid&&props.allowed&&!props.upgrade;
 try{const path=`/v2/commitments/${encodeURIComponent(cid)}/preparation/${encodeURIComponent(pid)}/materials`+(version?`/synthetic-reading/versions/${version}`:'');const value=await materialGet(path,signal,cid,pid);if(!same())return;if(!validResponse(value,cid,pid,version))throw Error('MATERIAL_INVALID');if(version&&!await verifyText(value.material))throw Error('MATERIAL_INVALID');if(!same())return;readRevision.value=value.context.preparationRevision;if(version)material.value=value.material;else entries.value=value.entries;status.value='';}catch(e){if(!same())return;if(e instanceof ApiError){status.value=e.status===404?'missing':[401,403,426].includes(e.status)?'denied':'failed';if([401,403].includes(e.status))emit('denied');}else status.value=e instanceof Error&&e.message.startsWith('MATERIAL_')?'invalid':'failed';}
}
watch(()=>[props.scope,props.epoch,props.cid,props.pid,props.allowed,props.upgrade],()=>close());
nextTick(()=>{if(!alive)return;dialog.value?.showModal();void read();});
onBeforeUnmount(()=>{alive=false;stop();dialog.value?.close();});
</script>
<template><dialog ref="dialog" id="material-reader" aria-labelledby="material-reader-title" @cancel.prevent="close"><header><h2 id="material-reader-title">{{t.title}}</h2><button id="material-language" type="button" @click="emit('language')">{{lang==='zh'?'English':'简体中文'}}</button><button id="material-close" type="button" @click="close">{{t.close}}</button></header><p id="material-boundary">{{t.boundary}}</p><p>{{t.source}} · p13-catalog-1</p><p>{{cid}} / {{pid}}</p><p v-if="readRevision">{{t.revision}} {{readRevision}}</p><p v-if="readRevision&&readRevision!==revision" role="status">{{t.changed}}</p><div class="versions"><button v-for="entry in entries" :id="'material-version-'+entry.versionId" :key="entry.versionId" type="button" :aria-pressed="selected===entry.versionId" @click="read(entry.versionId)">{{entry.title}} · {{t.version}} {{entry.versionId}}</button></div><p v-if="status" id="material-status" role="status">{{t[status]}}</p><p v-else-if="!material">{{t.empty}}</p><section v-if="material"><h3>{{material.title}} · {{material.versionId}}</h3><p id="material-hash">{{t.hash}}: {{material.sha256}}</p><pre id="material-plaintext">{{material.plainText}}</pre></section></dialog></template>
<style scoped>dialog{width:min(850px,90vw);max-height:85vh;overflow:auto;border:1px solid #8d9bad;border-radius:10px;padding:24px;color:#1d2c40;background:#fff}dialog::backdrop{background:#14243b88}header{display:flex;gap:12px;flex-wrap:wrap;align-items:center}header h2{flex:1}p{overflow-wrap:anywhere;line-height:1.6}.versions{display:flex;gap:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;line-height:1.7}button{padding:10px;cursor:pointer}</style>
